from __future__ import annotations

from fractions import Fraction as Fr
from itertools import combinations
from typing import Dict, List, Sequence, Tuple

Affine = Tuple[Fr, Fr, Fr]


def minimax_value(terms: Sequence[Affine]) -> Fr:
    if not terms:
        return Fr(0)
    val = lambda t, a, b: t[0] + t[1] * a + t[2] * b
    lines = [(Fr(1), Fr(0), Fr(0)), (Fr(1), Fr(0), Fr(1)), (Fr(0), Fr(1), Fr(0)), (Fr(0), Fr(1), Fr(1))]
    lines += [(s[1] - t[1], s[2] - t[2], t[0] - s[0]) for s, t in combinations(terms, 2)]
    best = None
    for (x1, y1, z1), (x2, y2, z2) in combinations(lines, 2):
        det = x1 * y2 - x2 * y1
        if det:
            a, b = (z1 * y2 - z2 * y1) / det, (x1 * z2 - x2 * z1) / det
            if 0 <= a <= 1 and 0 <= b <= 1:
                v = max(val(t, a, b) for t in terms)
                best = v if best is None or v < best else best
    return best if best is not None else Fr(0)


def delete_a_term_screen(named: Dict[str, Affine]) -> Tuple[Fr, List[str], List[str]]:
    """Prune redundant terms one at a time (re-screening after each prune).

    Returns (value, redundant terms in pruning order, load-bearing terms).
    """
    keep = dict(named)
    v0 = minimax_value(list(keep.values()))
    redundant: List[str] = []
    changed = True
    while changed:
        changed = False
        for name in list(keep):
            rest = [t for n, t in keep.items() if n != name]
            if minimax_value(rest) == v0:
                redundant.append(name)
                del keep[name]
                changed = True
                break
    return v0, redundant, list(keep)


if __name__ == "__main__":
    terms = {
        "M-leg (N/r)^(1/4)": (Fr(1, 4), Fr(-1, 4), Fr(0)),
        "interior": (Fr(1, 2), Fr(-1, 2), Fr(-1)),
        "pairs r": (Fr(0), Fr(1), Fr(0)),
        "baby-step m": (Fr(0), Fr(0), Fr(1)),
    }
    print(delete_a_term_screen(terms))
    # -> (1/5, ['M-leg (N/r)^(1/4)'], ['interior', 'pairs r', 'baby-step m'])

